import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmColourSwatchGroup } from './index';
import type { ZimmColourSwatchValue } from './index';

const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;
const mk = (value: string, name: string): ZimmColourSwatchValue => ({
  value,
  name,
  href: `/p.html?color=${value}`,
  imageUrl: IMAGE(value),
});

const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
  render(
    <ChakraProvider theme={theme}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <MemoryRouter>
          <ZimmColourSwatchGroup label="Colour" values={[mk('A', 'A'), mk('B', 'B'), mk('C', 'C')]} {...props} />
        </MemoryRouter>
      </IntlProvider>
    </ChakraProvider>,
  );

describe('SCRATCH probes (tester-only, deleted after use)', () => {
  test('non-paginated (3 colours) swatches width is plain 100%, not the paginated calc()', () => {
    renderGroup({ values: [mk('A', 'A'), mk('B', 'B'), mk('C', 'C')] });
    const styles = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' }));
    // eslint-disable-next-line no-console
    console.log('SCRATCH non-paginated width=', JSON.stringify(styles.width), 'minWidth=', JSON.stringify(styles.minWidth));
    expect(styles.width).toBe('100%');
  });

  test('5 populated colours: page 1 = 4 items, page 2 = exactly 1 item — width pinned on both', () => {
    const five = [mk('A', 'A'), mk('B', 'B'), mk('C', 'C'), mk('D', 'D'), mk('E', 'E')];
    renderGroup({ selectedName: 'E', selectedValue: 'E', values: five });

    // Selection is item index 4 (5th) -> should land directly on page 2 (the 1-item final page)
    // on first render, per selectedPageStart logic (floor(4/4)*4 = 4).
    const radiosInitial = screen.getAllByRole('radio');
    // eslint-disable-next-line no-console
    console.log('SCRATCH initial radio count (should be 1, landed on final single-item page)=', radiosInitial.length);
    console.log('SCRATCH initial radio names=', radiosInitial.map((r) => r.getAttribute('aria-label')));

    const stylesInitial = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' }));
    console.log('SCRATCH 5-colour final(1-item)-page width=', JSON.stringify(stylesInitial.width), 'minWidth=', JSON.stringify(stylesInitial.minWidth));
    expect(stylesInitial.width).toBe('calc(4 * var(--zimm-scale-1200))');
  });

  test('computed justify-content on swatches part (paginated, partial final page)', () => {
    const six = [mk('A', 'A'), mk('B', 'B'), mk('C', 'C'), mk('D', 'D'), mk('E', 'E'), mk('F', 'F')];
    renderGroup({ selectedName: 'F', selectedValue: 'F', values: six });
    const styles = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' }));
    // eslint-disable-next-line no-console
    console.log('SCRATCH justifyContent=', JSON.stringify(styles.justifyContent));
    console.log('SCRATCH display=', JSON.stringify(styles.display));
  });

  test('label row max width vs long colour name + pagination buttons present together', () => {
    const six = [mk('A', 'A'), mk('B', 'B'), mk('C', 'C'), mk('D', 'D'), mk('E', 'E'), mk('F', 'F')];
    const LONG = 'Antique Rose Gold Shimmer Sequin Embellished Iridescent Sunset Ombre';
    const { container } = renderGroup({ selectedName: LONG, selectedValue: 'A', values: six });
    // eslint-disable-next-line no-console
    console.log('SCRATCH long-name + paginated markup snapshot length=', container.innerHTML.length);
    const prevBtn = screen.getByRole('button', { name: /previous colours/i });
    expect(prevBtn).toBeInTheDocument();
  });
});
